@dataclass
class Member:
    member_id: str
    name: str
    birth: str              # YYYY-MM-DD
    phone: str              # digits only, 010xxxxxxxx
    channel: str
    status: str = PENDING
    kyc_state: str = KYC_NEW
    kyc_job: str = ""
    verdict: int = 0
